diff --git a/test/remove-api.test.ts b/test/remove-api.test.ts
new file mode 100644
index 0000000..7856701
--- /dev/null
+++ b/test/remove-api.test.ts
@@ -0,0 +1,16 @@
+import assert from "node:assert/strict";
+import { createServer } from "node:http";
+import type { AddressInfo } from "node:net";
+import { after, test } from "node:test";
+import { handle } from "../src/server.ts";
+
+const server = createServer(handle).listen(0);
+const base = `http://localhost:${(server.address() as AddressInfo).port}`;
+after(() => server.close());
+
+test("DELETE of an unknown todo is a 404 and deletes nothing", async () => {
+  await fetch(`${base}/api/todos`, { method: "POST", body: JSON.stringify({ title: "Stay" }) });
+  const before = await (await fetch(`${base}/api/todos`)).json();
+  assert.equal((await fetch(`${base}/api/todos/999`, { method: "DELETE" })).status, 404);
+  assert.deepEqual(await (await fetch(`${base}/api/todos`)).json(), before);
+});
